Problem statement:
Given n integers, print the largest sum of a non-empty contiguous subarray.

Input: the first line holds n (1 <= n <= 100000). The second line holds n integers a_1 .. a_n
(-1000000000 <= a_i <= 1000000000), separated by spaces.

Output: the maximum subarray sum followed by a newline. The subarray must contain at least one element,
so if every number is negative the answer is the largest (least negative) number. The answer may not fit
in a 32-bit int.

Sample input:
8
-2 1 -3 4 -1 2 1 -5

Sample output:
6

Student file brute_force.c:
  1 | /* Tries every subarray: correct, but O(n^2). */
  2 | #include <stdio.h>
  3 | 
  4 | static long long values[100000];
  5 | 
  6 | int main(void)
  7 | {
  8 |     int n;
  9 |     if (scanf("%d", &n) != 1) return 1;
 10 |     for (int i = 0; i < n; i++) scanf("%lld", &values[i]);
 11 |     long long best = values[0];
 12 |     for (int start = 0; start < n; start++) {
 13 |         long long sum = 0;
 14 |         for (int end = start; end < n; end++) {
 15 |             sum += values[end];
 16 |             if (sum > best) best = sum;
 17 |         }
 18 |     }
 19 |     printf("%lld\n", best);
 20 |     return 0;
 21 | }
